function validate([s, power, modulo, k, hashValue]) {
  if (typeof s !== 'string' || !/^[a-z]+$/.test(s)) return 's must be 1 or more lowercase letters.';
  if (s.length > 20000) return 's has at most 20000 letters.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and the length of s.';
  if (!Number.isInteger(power) || power < 1 || power > 1000000000) return 'power is between 1 and 10^9.';
  if (!Number.isInteger(modulo) || modulo < 1 || modulo > 1000000000) return 'modulo is between 1 and 10^9.';
  if (!Number.isInteger(hashValue) || hashValue < 0 || hashValue >= modulo) return 'hashValue is between 0 and modulo - 1.';
  const p = BigInt(power), m = BigInt(modulo), want = BigInt(hashValue);
  let top = 1n;
  for (let i = 0; i < k; i++) top = (top * p) % m;
  let hash = 0n;
  for (let i = s.length - 1; i >= 0; i--) {
    hash = (hash * p + BigInt(s.charCodeAt(i) - 96)) % m;
    if (i + k < s.length) hash = ((hash - BigInt(s.charCodeAt(i + k) - 96) * top) % m + m) % m;
    if (i + k <= s.length && hash === want) return null;
  }
  return 'No substring of length k has this hash; the problem guarantees one does.';
}

