  let hash = 0n;
  let start = 0;
  for (let i = n - 1; i >= 0; i--) {
    const entering = BigInt(s.charCodeAt(i) - 96);
    hash = (hash * p + entering) % m;
    if (i + k < n) {
      const leaving = BigInt(s.charCodeAt(i + k) - 96);
      hash = (hash - (leaving * powK) % m + m) % m;
    }
    if (i + k <= n && hash === target) {
      start = i;
    }
  }
  return s.slice(start, start + k);
}

