function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 10);
  const letters = rand() < 0.3 ? 2 : 26;
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  const k = size === 'large' && rand() < 0.5 ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * n);
  const big = rand() < 0.6;
  const power = big ? 1 + Math.floor(rand() * 1000000000) : 1 + Math.floor(rand() * 10);
  const modulo = big ? 1 + Math.floor(rand() * 1000000000) : 1 + Math.floor(rand() * 50);
  // Take the hash of a random window so that an answer always exists.
  const at = Math.floor(rand() * (n - k + 1));
  const p = BigInt(power), m = BigInt(modulo);
  let hash = 0n, weight = 1n;
  for (let j = 0; j < k; j++) {
    hash = (hash + BigInt(s.charCodeAt(at + j) - 96) * weight) % m;
    weight = (weight * p) % m;
  }
  return [s, power, modulo, k, Number(hash)];
}
